+      final mergeRuns = <String>[];
+      for (final step in gate['steps'] as YamlList) {
+        if (step is YamlMap && step['run'].toString().contains('pty shard coverage reports')) {
+          mergeRuns.add(step['run'].toString());
+        }
+      }
+      expect(mergeRuns, hasLength(1));
